// ==========================================

epicSlot('gate', 'driver').push(
{ title:'성문 — 둘이 민다',
  text:`축이 휜 마차는 끌어서는 안 간다.<br><br>
    뒤에서 밀어야 한다.<br>
    혼자면 밀면서 방향을 못 잡는다.<br><br>
    하나가 끌채를 잡고 하나가 밀어야 한다.`,
  opts:[
    { l:'① 동료가 민다.', co:'sync',
      coOpt:{ ask:'뒤에서 밀어 주십시오. 제가 방향을 잡겠습니다.', sec:60, p:1000,
        text:`혼자면 밀면서 방향을 못 잡는다.`,
        doneText:`끌채를 잡고 저쪽이 밀었다. 한 뼘씩 움직인다.<br><br>축이 삐걱인다. 세 걸음 옮기고 그만뒀다.<br>뒤에 이어진 것들이 따라 움직였다. 스물셋 대가 다.<br><br>도로 놓았다. 옮길 수 있다는 것만 알면 됐다.<br>저쪽 손이 벌겠다. 밀 데가 거칠어서 그렇다.`,
        failText:`혼자 끌었다. 안 움직인다.<br><br>축이 휘어서 바퀴가 안 돈다.<br>세 번 당기고 그만뒀다.` },
      good:`세 걸음 옮겼다.`, bad:`못 움직였다.`, flag:'movedOneCart' },
    { l:'② 짐 무게를 견준다.', mini:'scale', miniOpt:{ p:800, target:24, pool:[4,5,7,8,10,11] },
      good:`양쪽 무게를 견줘 봤다.<br><br>맞췄다. 스물셋 대가 전부 고르게 실렸다.<br>잘 실었다. 솜씨 있는 사람이 실었다.<br><br>잘 싣고 안 갔다. 갈 생각이었는데 못 갔다.`, flag:'loadedWell',
      bad:`한쪽이 무겁다.<br><br>스물셋 대가 다 같은 쪽으로 기울어 있다.<br>일부러 그렇게 실은 것 같다.` }
  ] }
);

epicSlot('road', 'driver').push(
{ title:'끊긴 길 — 둘이 싣는다',
  text:`짐을 싣는 건 둘이 한다.<br><br>
    혼자 실으면 한쪽으로 쏠린다.<br>
    양쪽에서 같이 올려야 고르다.<br><br>
    쏠린 마차는 바퀴가 나간다.`,
  opts:[
    { l:'① 동료와 양쪽에서 싣는다.', co:'sync',
      coOpt:{ ask:'저쪽에서 같이 올려 주십시오. 한 번에 한 개씩.', sec:60, p:1000,
        text:`혼자 실으면 한쪽으로 쏠린다.`,
        doneText:`한 개씩 번갈아 올렸다. 왼쪽 하나, 오른쪽 하나.<br><br>다 싣고 밀어 봤다. 곧게 굴러간다.<br>기울지 않는다.<br><br>저쪽이 이게 왜 중요하냐고 물었다.<br>기울면 다리에서 뒤집힌다고 했다. 여기 다리가 있다.`,
        failText:`혼자 실었다. 한쪽부터 쌓다 보니 기운다.<br><br>옮겨 실으려니 두 번 일이다.<br>기운 채로 뒀다. 천천히 가기로 했다.` },
      good:`고르게 실었다.`, bad:`기울었다.`, flag:'balancedLoad' },
    { l:'② 다리 널을 두드린다.', mini:'beat', miniOpt:{ p:750, total:10, gap:700 },
      good:`한 칸씩 두드렸다. 열 번.<br><br>빈 소리가 셋. 널이 없는 자리다.<br>세 번째, 일곱 번째, 아홉 번째.<br><br>외워 뒀다. 건널 때 피하면 된다.`, flag:'threeGaps',
      bad:`두드리는 소리에 아래가 반응한다.<br><br>같은 박자로 되두드린다. 박자를 바꿔 봤다.<br>따라 바뀐다.` }
  ] }
);

epicSlot('village', 'driver').push(
{ title:'빈 마을 — 둘이 자국을 읽는다',
  text:`바퀴 자국이 겹쳐 있다.<br><br>
    혼자 읽으면 몇 번인지 모른다.<br>
    하나가 한쪽 바퀴를 세고 하나가 다른 쪽을 세면 갈린다.<br><br>
    두 바퀴가 같은 수면 맞는 것이다.`,
  opts:[
    { l:'① 동료와 바퀴를 나눠 센다.', co:'sync',
      coOpt:{ ask:'오른쪽 바퀴 자국만 세 주십시오. 제가 왼쪽을 세겠습니다.', sec:60, p:1000,
        text:`두 바퀴가 같은 수면 맞는 것이다.`,
        doneText:`갈라 셌다. 둘 다 스물셋이라 했다.<br><br>스물셋 번 드나들었다. 집 수와 같다.<br>한 집에 한 번씩이다.<br><br>저쪽이 물었다. 한 번에 여러 집을 돌면 되지 않냐고.<br>그러면 자국이 안 겹친다고 했다. 한 번에 하나씩 갔다.`,
        failText:`혼자 셌다. 겹쳐서 몇 번인지 모르겠다.<br><br>열다섯쯤 세다가 놓쳤다.<br>여러 번 왔다는 것만 알았다.` },
      good:`스물셋 번이다.`, bad:`모르겠다.`, flag:'twentyThreeTrips' },
    { l:'② 자국 깊이를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`들어온 자국과 나간 자국 깊이를 견줬다.<br><br>맞췄다. 들어온 쪽이 훨씬 깊다.<br>싣고 와서 내려놓고 빈 채로 갔다.<br><br>스물셋 번 다 그렇다. 한 번도 안 싣고 갔다.`, flag:'alwaysEmptyOut',
      bad:`깊이가 제각각이다.<br><br>어떤 건 나갈 때 더 깊다.<br>견줄 수가 없다.` }
  ] }
);

epicSlot('market', 'driver').push(
{ title:'장터 — 둘이 묶는다',
  text:`짐 묶는 매듭은 둘이 한다.<br><br>
    하나가 당기고 하나가 묶는다.<br>
    혼자 묶으면 느슨해진다.<br><br>
    느슨하면 가다가 풀린다.`,
  opts:[
    { l:'① 동료와 다시 묶는다.', co:'handoff',
      coOpt:{ ask:'끈이 삭았습니다. 당겨 주시면 다시 묶겠습니다.', sec:60, p:1000,
        text:`혼자 묶으면 느슨해진다.`,
        doneText:`저쪽이 당기고 이쪽이 묶었다. 마부 매듭으로.<br><br>삭은 끈을 갈았다. 세 좌판 분을 했다.<br>나머지는 끈이 없어서 못 했다.<br><br>저쪽이 왜 남의 짐을 묶냐고 물었다.<br>실을 사람이 오면 바로 싣게, 라고 했다. 올지는 모른다.`,
        failText:`혼자 묶었다. 한 손으로 당기고 한 손으로 묶으니 느슨하다.<br><br>당기면 풀린다. 두 번 하고 그만뒀다.` },
      good:`세 좌판을 묶었다.`, bad:`느슨했다.`, flag:'retiedThree' },
    { l:'② 한 좌판 분 무게를 견준다.', mini:'scale', miniOpt:{ p:750, target:22, pool:[3,5,6,8,9,12] },
      good:`한 무더기 무게를 어림해 견줬다.<br><br>맞췄다. 마차 한 대 분이다. 정확히.<br>좌판 하나에 마차 하나. 스물셋에 스물셋.<br><br>맞춰서 쌓아 둔 것이다. 누가 셈을 해 뒀다.`, flag:'oneCartEach',
      bad:`무게가 안 잡힌다.<br><br>어림할 때마다 다르다. 들어 보지는 않았다.<br>그만뒀다.` }
  ] }
);

epicSlot('castle', 'driver').push(
{ title:'성 — 둘이 칸을 본다',
  text:`칸이 스물셋이다.<br><br>
    혼자 세면 헷갈린다. 칸이 다 비슷하다.<br>
    하나가 짚고 하나가 세면 안 헷갈린다.<br><br>
    짚는 쪽은 안 센다.`,
  opts:[
    { l:'① 동료가 짚는다.', co:'sync',
      coOpt:{ ask:'칸을 하나씩 짚어 주십시오. 제가 세겠습니다.', sec:60, p:1000,
        text:`짚는 쪽은 안 센다.`,
        doneText:`저쪽이 짚고 이쪽이 셌다. 스물셋.<br><br>짚어 가다 저쪽이 멈췄다. 한 칸만 문이 있다고 했다.<br>나머지 스물둘은 트여 있는데 하나만 문이 있다.<br><br>문은 바깥에서 잠근다. 안에서는 못 연다.<br>안 열었다. 둘 다 안 열자고 했다.`,
        failText:`혼자 셌다. 스물셋이었다가 스물둘이 된다.<br><br>칸이 다 비슷해서 어디까지 셌는지 모르겠다.<br>문 있는 칸은 못 찾았다.` },
      good:`문 있는 칸을 찾았다.`, bad:`못 찾았다.`, flag:'oneStallHasDoor' },
    { l:'② 칸 폭을 견준다.', mini:'scale', miniOpt:{ p:750, target:19, pool:[2,3,5,6,8,10] },
      good:`칸 폭을 견줬다.<br><br>맞췄다. 스물둘이 같다. 어깨 폭보다 조금 넓다.<br>문 있는 하나만 넓다. 두 배쯤.<br><br>둘이 들어갈 만하다. 아니면 하나가 눕거나.`, flag:'oneWiderStall',
      bad:`폭이 제각각이다.<br><br>재는 동안 좁아진다. 그만뒀다.` }
  ] }
);

epicSlot('temple', 'driver').push(
{ title:'신전 — 둘이 비탈을 오른다',
  text:`비탈이 가파르다.<br><br>
    혼자 끌면 미끄러진다.<br>
    하나가 끌고 하나가 뒤를 받쳐야 한다.<br><br>
    뒤를 안 받치면 내려온다.`,
  opts:[
    { l:'① 동료가 뒤를 받친다.', co:'standin',
      coOpt:{ ask:'뒤를 받쳐 주십시오. 내려오면 위험합니다.', sec:60, p:1050,
        text:`뒤를 안 받치면 내려온다.`,
        doneText:`빈 수레를 하나 찾아 끌고 올랐다. 저쪽이 뒤를 받쳤다.<br><br>제단 앞까지 갔다. 바퀴가 딱 맞는다. 비탈이 이 폭에 맞춰져 있다.<br>제단 앞에 바퀴 멈춤 돌이 있다. 대면 안 굴러간다.<br><br>대 보고 내려왔다. 내려올 때도 저쪽이 받쳤다.<br>혼자면 내려오다 다쳤을 것이다.`,
        failText:`혼자 끌었다. 반쯤 올라가서 미끄러졌다.<br><br>수레가 내려온다. 피했다.<br>아래에서 부딪쳐 멈췄다. 다시 안 끌었다.` },
      good:`제단까지 갔다.`, bad:`미끄러졌다.`, flag:'wheelStopAtAltar' },
    { l:'② 오간 자국을 센다.', mini:'beat', miniOpt:{ p:750, total:10, gap:720 },
      good:`겹친 자국을 세었다. 열 번.<br><br>여덟 번 오갔다. 올라간 게 여덟, 내려온 게 여덟.<br>수가 맞는다.<br><br>여덟 번 싣고 올라가 여덟 번 빈 채로 내려왔다.`, flag:'eightUpEightDown',
      bad:`세다가 겹친다.<br><br>올라간 건지 내려온 건지 모르겠다.<br>그만 셌다.` }
  ] }
);

epicSlot('grave', 'driver').push(
{ title:'묘지 — 둘이 따라간다',
  text:`흙을 실어 온 자국이 있다.<br><br>
    혼자 따라가면 갈라진 데서 놓친다.<br>
    둘이 갈라지면 둘 다 본다.<br><br>
    자국은 대개 갈라진다.`,
  opts:[
    { l:'① 동료와 갈라져 따라간다.', co:'sync',
      coOpt:{ ask:'갈라지는 데가 나오면 한쪽씩 맡읍시다. 멀리는 가지 마시고.', sec:60, p:1000,
        text:`자국은 대개 갈라진다.`,
        doneText:`성문 쪽으로 따라가다 갈라졌다. 각자 맡았다.<br><br>저쪽 것은 성문으로 이어졌다. 이쪽 것은 안뜰 쪽이다.<br>안뜰에 파낸 데가 있다. 넓다.<br><br>거기 흙을 실어 왔다. 마구간 옆이다.<br>파낸 자리가 칸 하나만큼이다.`,
        failText:`혼자 따라갔다. 갈라진 데서 한쪽만 골랐다.<br><br>성문까지 갔다. 다른 쪽은 못 봤다.<br>어디서 실었는지는 모른다.` },
      good:`판 자리를 찾았다.`, bad:`성문까지만 갔다.`, flag:'foundTheSource' },
    { l:'② 자국 깊이를 견준다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,10] },
      good:`오는 자국과 가는 자국을 견줬다.<br><br>맞췄다. 올 때 깊고 갈 때 얕다.<br>흙을 싣고 와서 내려놓고 빈 채로 갔다.<br><br>스물셋 번 다 그렇다. 한 번도 안 싣고 갔다.`, flag:'soilOnlyIn',
      bad:`한 번만 갈 때가 더 깊다.<br><br>마지막 한 번이다. 뭔가 싣고 갔다.<br>그만뒀다.` }
  ] }
);

epicSlot('tower', 'driver').push(
{ title:'탑 — 둘이 본다',
  text:`위에서 자국이 다 보인다.<br><br>
    혼자 보면 한쪽만 본다.<br>
    나눠 보면 전체가 나온다.<br><br>
    전체를 봐야 어디가 시작인지 안다.`,
  opts:[
    { l:'① 동료와 나눠 본다.', co:'sync',
      coOpt:{ ask:'저쪽 반을 봐 주십시오. 자국이 어디로 가는지만.', sec:60, p:1000,
        text:`전체를 봐야 시작이 보인다.`,
        doneText:`갈라 봤다. 저쪽이 묘지와 신전 쪽을 봤다.<br><br>합쳐 보니 전부 성문으로 모인다. 넷으로 뻗고 넷으로 온다.<br>다만 한 줄이 더 있다. 성문에서 나가서 안 돌아온다.<br><br>어디로 가는지는 둘 다 못 봤다. 중간에서 끊긴다.<br>끊긴 데가 숲 가장자리다.`,
        failText:`혼자 봤다. 넷까지 세고 못 셌다.<br><br>반대쪽은 안 보인다.<br>몇 갈래인지 모르겠다.` },
      good:`다섯째 줄을 봤다.`, bad:`넷만 봤다.`, flag:'fifthTrack' },
    { l:'② 자국 깊이를 견준다.', mini:'scale', miniOpt:{ p:750, target:23, pool:[3,5,6,8,10,12] },
      good:`갈래마다 깊이를 견줬다.<br><br>맞췄다. 묘지 쪽이 제일 깊고 신전 쪽이 다음이다.<br>스물셋과 여덟. 수와 맞는다.<br><br>끊긴 다섯째 줄은 한 번 분이다. 한 번만 갔다.`, flag:'fifthWentOnce',
      bad:`깊이가 안 잡힌다.<br><br>멀어서 그렇다. 어림이 안 된다.<br>그만뒀다.` }
  ] }
);

epicSlot('lake', 'driver').push(
{ title:'거울 호수 — 둘이 내린다',
  text:`길쭉한 것을 내렸다.<br><br>
    혼자 내리면 떨어뜨린다.<br>
    양쪽에서 들어 내려야 한다.<br><br>
    마부는 내리는 법을 먼저 배운다.`,
  opts:[
    { l:'① 동료와 자국을 견준다.', co:'witness',
      coOpt:{ ask:'이 눌린 자국을 봐 주십시오. 몇 사람 자국인지.', sec:60, p:1000,
        text:`양쪽에서 들어 내렸다면 자국이 둘이다.`,
        doneText:`둘이 엎드려 봤다. 눌린 자국 양옆에 발자국이 있다.<br><br>두 쌍이다. 마주 보고 섰다.<br>둘이 들어 내렸다는 뜻이다.<br><br>저쪽이 발 크기가 다르다고 했다. 하나는 크고 하나는 작다.<br>작은 쪽이 폐허 우리 안 자국과 비슷하다. 말은 안 했다.`,
        failText:`혼자 봤다. 눌린 자국만 보인다.<br><br>주변 발자국은 못 찾았다.<br>혼자 내렸는지 둘이 내렸는지 모른다.` },
      good:`두 사람이었다.`, bad:`모르겠다.`, flag:'twoUnloaded' },
    { l:'② 내린 것의 길이를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`눌린 자국 길이를 재 견줬다.<br><br>맞췄다. 어른 키만 하다.<br>여덟 개가 같은 길이다.<br><br>같은 것을 여덟 번 내렸다. 신전 오간 수와 같다.`, flag:'eightSameLength',
      bad:`길이가 제각각이다.<br><br>어떤 건 짧고 어떤 건 길다.<br>견줄 수가 없다.` }
  ] }
);

epicSlot('ruin', 'driver').push(
{ title:'폐허 — 둘이 바퀴를 본다',
  text:`바퀴가 빠진 마차가 있다.<br><br>
    혼자 축을 보면 못 든다. 무겁다.<br>
    하나가 들고 하나가 봐야 한다.<br><br>
    들어 봐야 어떻게 빠졌는지 안다.`,
  opts:[
    { l:'① 동료가 든다.', co:'sync',
      coOpt:{ ask:'축을 조금만 들어 주십시오. 제가 아래를 보겠습니다.', sec:60, p:1000,
        text:`들어 봐야 어떻게 빠졌는지 안다.`,
        doneText:`저쪽이 축을 들었다. 이쪽이 아래를 봤다.<br><br>축 끝이 매끈하다. 도구로 풀었다. 부러진 게 아니다.<br>일부러 뺐다.<br><br>빼고 어디 뒀는지는 모른다. 근처에 없다.<br>저쪽이 팔이 떨린다고 해서 놓으라고 했다. 쿵 소리가 났다.`,
        failText:`혼자 들어 보려 했다. 한 뼘도 못 들었다.<br><br>아래는 못 봤다.<br>빠진 건지 뺀 건지 모른다.` },
      good:`뺀 것을 확인했다.`, bad:`못 봤다.`, flag:'confirmedRemoval' },
    { l:'② 짐칸 자국을 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`짐칸 바닥 눌린 자국을 순서대로 짚었다. 여섯 자리.<br><br>맞췄다. 길쭉한 게 나란히 놓였던 자국이다.<br>한 번에 셋씩. 두 번 실었다.<br><br>여섯이다. 여덟에서 둘이 모자란다.`, flag:'sixNotEight',
      bad:`자국이 겹쳐 있다.<br><br>여러 번 실었다. 순서를 못 잡겠다.<br>그만뒀다.` }
  ] }
);

epicSlot('forest', 'driver').push(
{ title:'검은 숲 — 둘이 돌린다',
  text:`마차를 돌릴 만한 데가 가장자리뿐이다.<br><br>
    혼자 돌리면 바퀴가 나간다.<br>
    하나가 끌채를 돌리고 하나가 뒤를 밀어야 한다.<br><br>
    돌리는 자리를 잘 보면 몇 대가 왔는지 안다.`,
  opts:[
    { l:'① 동료와 돌린 자국을 읽는다.', co:'sync',
      coOpt:{ ask:'돌린 자국이 몇 개인지 봐 주십시오. 제가 방향을 보겠습니다.', sec:60, p:1000,
        text:`돌린 자국으로 몇 대가 왔는지 안다.`,
        doneText:`저쪽이 세고 이쪽이 방향을 봤다.<br><br>스물셋 번 돌렸다. 전부 같은 자리에서.<br>방향은 다 같다. 들어오다 돌아나갔다.<br><br>한 번도 안 들어갔다. 가장자리까지 오고 돌아갔다.<br>마차로는 못 들어간다는 걸 스물셋 번 확인한 셈이다.`,
        failText:`혼자 봤다. 자국이 겹쳐서 몇 번인지 모르겠다.<br><br>여러 번 돌렸다는 것만 알았다.<br>방향은 못 봤다.` },
      good:`스물셋 번이다.`, bad:`모르겠다.`, flag:'turnedTwentyThree' },
    { l:'② 트인 줄 폭을 잰다.', mini:'scale', miniOpt:{ p:750, target:18, pool:[2,3,5,6,8,9] },
      good:`폭을 바퀴 사이와 견줬다.<br><br>맞췄다. 절반도 안 된다.<br>수레가 아니라 사람만 지나는 폭이다.<br><br>안에서 뭘 꺼내려면 들고 나와야 한다.`, flag:'mustCarryOut',
      bad:`폭이 안 잡힌다.<br><br>재는 동안 넓어진다. 바퀴가 지날 만해진다.<br>그만뒀다.` }
  ] }
);
;

// ---------- epic-driver-3.js ----------
// ==========================================
// ★ 마부 확장 3/4
// index.html 에서 epic-driver-2.js 다음에 불러온다
// ==========================================

epicSlot('castle', 'driver').push(
{ title:'성 — 문 있는 칸',
  text:`칸 하나에만 문이 있다.<br><br>
    바깥에서 잠근다.<br>
    마부는 잠그는 칸을 안다. 성질 사나운 것을 넣는다.<br><br>
    다만 여기는 말을 안 맸다.`,
  opts:[
    { l:'① 문을 밖에서 본다.', dc:13, kind:'gaze', p:800,
      good:`빗장에 손때가 깊다. 여러 번 열고 닫았다.<br><br>안쪽에도 자국이 있다. 문틈으로 손이 나온 자국.<br>밖에서 열어 주기를 기다린 자국이다.<br><br>손 크기가 작다. 안 열었다.`, flag:'smallHandAtDoor',
      bad:`빗장이 조금 움직인다.<br><br>안에서 미는 것처럼. 손을 안 댔는데.<br>물러났다.`, poll:9 },
    { l:'② 문을 연다.', dc:14, kind:'break', p:800,
      doom:{ title:'연 문', what:'칸이 비었습니다', dc:14, sec:70,
        text:`빗장을 밀었다. 잘 밀린다. 손때가 깊어서 그렇다.<br><br>안이 비어 있다. 다만 바닥이 다져져 있다.<br>오래 서 있었다. 한 자리에서.<br><br>문을 열면 칸이 빈 칸이 된다. 빈 칸은 채워야 한다.<br>마부는 빈 칸을 못 지나친다. 뭐든 넣게 된다.`,
        dieText:`문 있는 칸은 잠가 두는 것이다.<br><br>열면 비고 비면 채워진다.<br>마구간에 칸이 스물셋이다. 하나만 문이 있다.` },
      good:`빗장에 손을 댔다가 뗐다.<br><br>밖에서 잠그는 문이다. 안에 뭘 넣으려고 만든 것이다.<br>열면 비고 비면 채우게 된다.<br><br>안 열었다. 빗장을 한 번 더 밀어 단단히 했다.`, flag:'leftItBarred' }
  ] }
);

epicSlot('grave', 'driver').push(
{ title:'묘지 — 안뜰에서 판 흙',
  text:`안뜰 마구간 옆을 팠다.<br><br>
    판 자리가 칸 하나만큼이다.<br>
    마부는 크기를 본다. 크기가 말해 준다.<br><br>
    칸 하나 분 흙으로 봉분 스물셋을 못 덮는다.`,
  opts:[
    { l:'① 양이 맞는지 본다.', dc:13, kind:'sense', p:800,
      good:`판 자리가 마차 다섯 대 분쯤이다.<br><br>스물셋 번 실어 왔다고 했는데 판 자리는 다섯 대 분이다.<br>수가 안 맞는다.<br><br>나머지 열여덟은 다른 데서 왔다. 안뜰만이 아니다.`, flag:'notEnoughSoil',
      bad:`판 자리가 넓어진다.<br><br>보는 동안. 스물셋 대 분이 된다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 판 자리를 파 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'다시 판 자리', what:'바닥이 나왔습니다', dc:14, sec:70,
        text:`메워진 데를 다시 팠다. 흙이 무르다.<br><br>바닥이 나온다. 돌이다. 판판하다.<br>뚜껑이다. 칸 하나만 한 뚜껑.<br><br>파낸 흙은 이 뚜껑을 덮고 있던 것이다.<br>덮은 걸 치우면 안 눌린다. 마부는 무게를 다루는 사람이라 그걸 안다.`,
        dieText:`흙은 덮으려고 쌓는다.<br><br>파내면 덮이던 게 안 덮인다.<br>안뜰에 구덩이가 하나 있다.` },
      good:`삽을 댔다가 거뒀다.<br><br>파낸 흙이 스물셋 대 분이 아니다. 판 자리보다 많이 나왔다.<br>그러면 아래에 뭐가 있었다는 뜻이다.<br><br>안 팠다. 흙을 오히려 더 덮었다.`, flag:'didntReopen' }
  ] }
);

epicSlot('market', 'driver').push(
{ title:'장터 — 셈을 해 둔 사람',
  text:`좌판 하나에 마차 하나씩 맞춰 놨다.<br><br>
    누가 셈을 해 뒀다.<br>
    마부는 셈해 둔 짐을 안다. 실을 준비가 된 것이다.<br><br>
    준비만 하고 안 실었다.`,
  opts:[
    { l:'① 왜 안 실었는지 본다.', dc:13, kind:'gaze', p:800,
      good:`좌판 옆에 바퀴 자국이 있다. 마차가 왔었다.<br><br>와서 돌아갔다. 싣지 않고.<br>실을 사람이 없었거나 실으면 안 됐거나.<br><br>끌채 자국이 없다. 끌 사람 없이 온 마차다.`, flag:'cartsCameEmptyHanded',
      bad:`실린 자국이 있다. 한 좌판만 비었다.<br><br>스물둘이 남았다. 하나는 실려 갔다.<br>세어 보니 스물둘이다.`, poll:9 },
    { l:'② 한 좌판 분을 실어 본다.', dc:14, p:800,
      doom:{ title:'실은 짐', what:'셈이 시작됐습니다', dc:14, sec:70,
        text:`근처 빈 수레에 한 좌판 분을 실었다. 맞나 보려고.<br><br>딱 맞는다. 셈해 둔 대로다.<br>싣고 나니 수레가 저절로 굴러간다. 성문 쪽으로.<br><br>실으면 간다. 셈해 둔 짐은 갈 데가 정해져 있다.<br>마부는 실은 걸 안 놓는다. 끌채를 잡고 따라갔다.`,
        dieText:`셈해 둔 짐은 실으면 간다.<br><br>가는 데가 어디인지는 싣기 전에는 모른다.<br>좌판이 스물둘이다.` },
      good:`손을 댔다가 거뒀다.<br><br>셈해 둔 짐이다. 실으면 갈 데가 정해진다.<br>정해진 데가 어디인지 모르는 채로 실으면 안 된다.<br><br>안 실었다. 묶인 채로 뒀다.`, flag:'didntLoadIt' }
  ] }
);

epicSlot('temple', 'driver').push(
{ title:'신전 — 바퀴 멈춤 돌',
  text:`제단 앞에 바퀴 멈춤 돌이 있다.<br><br>
    대면 안 굴러간다.<br>
    마부는 멈춤 돌을 본다. 거기가 내리는 자리다.<br><br>
    여덟 번 댔다.`,
  opts:[
    { l:'① 돌에 난 자국을 본다.', dc:13, kind:'sense', p:800,
      good:`바퀴가 닿은 자국이 여덟이다. 겹쳐 있다.<br><br>같은 자리에 여덟 번 댔다. 정확히 같은 자리에.<br>정확하려면 익숙해야 한다.<br><br>같은 사람이 여덟 번 댔다.`, flag:'eightStops',
      bad:`자국이 아홉이다.<br><br>하나는 조금 어긋나 있다. 서툰 사람이 댔다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 멈춤 돌을 치운다.', dc:14, kind:'break', p:800,
      doom:{ title:'치운 돌', what:'비탈이 열렸습니다', dc:14, sec:70,
        text:`멈춤 돌을 굴려 치웠다. 길을 트려고.<br><br>치우자 비탈이 제단 아래까지 곧게 이어진다.<br>멈춤 돌이 막고 있던 것이다. 제단 앞이 아니라 그 아래로.<br><br>수레가 굴러간다. 빈 수레가. 안 밀었는데.<br>마부는 굴러가는 수레를 쫓는다. 몸이 먼저 간다.`,
        dieText:`멈춤 돌은 멈추라고 놓는다.<br><br>치우면 안 멈춘다.<br>제단 아래로 비탈이 이어져 있다.` },
      good:`손을 대다가 거뒀다.<br><br>멈춤 돌은 멈추라고 놓은 것이다.<br>치우면 안 멈추고 안 멈추면 어디까지 가는지 모른다.<br><br>안 치웠다. 오히려 하나 더 괴어 뒀다.`, flag:'addedAnotherChock' }
  ] }
);

epicSlot('village', 'driver').push(
{ title:'빈 마을 — 한 번도 안 싣고 갔다',
  text:`스물셋 번 다 빈 채로 나갔다.<br><br>
    싣고 와서 내려놓기만 했다.<br>
    마부는 빈 마차로 돌아가는 걸 싫어한다.<br><br>
    한 번쯤은 싣고 가게 마련이다.`,
  opts:[
    { l:'① 왜 안 실었는지 본다.', dc:13, kind:'gaze', p:800,
      good:`마당에 실을 만한 게 없다. 처음부터 없었다.<br><br>가져갈 게 없는 마을이다.<br>주기만 하고 받을 게 없었다.<br><br>스물셋 번 주고 스물셋 번 빈 채로 갔다.`, flag:'nothingToTakeBack',
      bad:`실을 게 있다. 마당마다 하나씩.<br><br>한 뼘짜리 묻힌 것들이다. 그건 실을 게 아니다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 마지막 자국을 본다.', dc:14, p:800,
      doom:{ title:'마지막 자국', what:'싣고 갔습니다', dc:14, sec:70,
        text:`제일 나중 자국을 찾았다. 제일 위에 겹친 것.<br><br>나갈 때가 더 깊다. 스물셋 번 중 한 번만 그렇다.<br>마지막에 뭔가 싣고 갔다.<br><br>무게로 보면 사람 하나 분이다.<br>마부는 무게로 안다. 알고 나면 어디로 갔는지 따라가게 된다.`,
        dieText:`마지막에 실은 것을 알면 어디로 갔는지 궁금해진다.<br><br>궁금하면 따라간다. 마부는 자국을 따라간다.<br>마을 밖으로 자국이 이어진다.` },
      good:`겹친 자국을 풀어 보다 그만뒀다.<br><br>마지막 한 번만 알면 되는데, 알면 따라가게 된다.<br>마부는 자국을 따라가는 버릇이 있다.<br><br>안 봤다. 스물셋 번 다 빈 채로 갔다고 쳤다.`, flag:'didntCheckLast' }
  ] }
);

epicSlot('tower', 'driver').push(
{ title:'탑 — 다섯째 줄',
  text:`성문에서 나가서 안 돌아온 자국이 하나 있다.<br><br>
    한 번만 갔다.<br>
    마부는 안 돌아온 자국을 오래 본다.<br><br>
    끊긴 데가 숲 가장자리다.`,
  opts:[
    { l:'① 어디서 끊기는지만 본다.', dc:13, kind:'gaze', p:800,
      good:`가장자리에서 끊긴다. 돌린 자국이 없다.<br><br>돌리지 않고 끊겼다. 거기서 멈춰서 그대로다.<br>마차는 지금 거기 있어야 한다.<br><br>위에서 보면 없다. 마차가 안 보인다.`, flag:'cartNotThere',
      bad:`끊긴 자리에 뭐가 있다.<br><br>작다. 마차는 아니다. 볼수록 커진다.<br>눈을 뗐다.`, poll:9 },
    { l:'② 무게를 어림한다.', dc:14, p:800,
      doom:{ title:'어림한 무게', what:'실려 있었습니다', dc:14, sec:70,
        text:`자국 깊이로 실린 무게를 어림했다.<br><br>깊다. 스물셋 대 중 제일 깊다.<br>한 대에 실을 수 있는 최대다.<br><br>그만큼 싣고 한 번 나가서 안 돌아왔다.<br>마부는 무게를 어림하면 뭐가 실렸는지 알게 된다. 알고 나면 잊히지 않는다.`,
        dieText:`실린 무게를 알면 실린 것을 안다.<br><br>알면 확인하러 가게 된다.<br>탑 위에 아무도 없다.` },
      good:`어림하다 그만뒀다.<br><br>무게를 알면 뭐가 실렸는지 안다.<br>알면 확인하러 가게 된다. 마부는 실린 걸 확인하는 게 일이다.<br><br>깊다는 것만 적었다. 얼마나인지는 안 적었다.`, flag:'loggedDeepOnly' }
  ] }
);

epicSlot('lake', 'driver').push(
{ title:'거울 호수 — 여덟과 여섯',
  text:`여기서 여덟 번 내렸다.<br><br>
    폐허 짐칸에는 여섯 자국이다.<br>
    마부는 수가 안 맞으면 못 넘긴다.<br><br>
    둘이 모자란다.`,
  opts:[
    { l:'① 다른 마차가 있었나 본다.', dc:13, kind:'sense', p:800,
      good:`물가 자국을 다시 봤다. 바퀴 폭이 둘이다.<br><br>넓은 것과 좁은 것. 넓은 게 여섯 번, 좁은 게 두 번이다.<br>마차가 둘이었다.<br><br>둘이면 수가 맞는다. 폐허 것이 넓은 쪽이다.`, flag:'twoCarts',
      bad:`폭이 셋이다.<br><br>세 번째 것은 아주 좁다. 손수레쯤이다.<br>안 세었다.`, poll:9 },
    { l:'② 물에 들어간 자국을 따라간다.', dc:14, kind:'evade', p:800,
      doom:{ title:'따라간 자국', what:'얕았습니다', dc:14, sec:70,
        text:`물에 들어간 바퀴 자국을 따라 걸었다. 얕다. 발목까지.<br><br>자국이 이어진다. 물 아래에도 바닥이 있다.<br>한참 갔다. 여전히 발목까지다.<br><br>돌아보니 물가가 멀다. 발목까지인데 멀다.<br>마부는 바퀴가 간 데는 갈 수 있다고 생각한다. 바퀴는 안 돌아왔는데.`,
        dieText:`바퀴가 간 데를 따라가면 바퀴가 간 데까지 간다.<br><br>바퀴가 안 돌아왔으면 따라간 쪽도 안 돌아온다.<br>물가에 바퀴 자국이 하나 더 늘었다.` },
      good:`물가에서 멈췄다.<br><br>바퀴가 들어가고 안 나왔다. 그러면 따라가도 안 나온다.<br>마부는 바퀴가 간 데는 갈 수 있다고 여기는데, 그게 여기서는 틀렸다.<br><br>안 들어갔다.`, flag:'didntFollowIn' }
  ] }
);

epicSlot('ruin', 'driver').push(
{ title:'폐허 — 여섯 번 실었다',
  text:`짐칸에 여섯 자국이다.<br><br>
    한 번에 셋씩 두 번 실었다.<br>
    마부는 싣는 횟수로 급한 정도를 안다.<br><br>
    한 번에 많이 실으면 급한 것이다.`,
  opts:[
    { l:'① 실은 순서를 본다.', dc:13, kind:'sense', p:800,
      good:`아래쪽 세 자국이 깊다. 먼저 실은 것이다.<br><br>위쪽 셋은 얕다. 나중에 얹었다.<br>두 번 나눠 실은 게 아니라 한 번에 여섯을 쌓았다.<br><br>쌓아서 실었다. 한 번에 다 가려고 했다.`, flag:'stackedSix',
      bad:`자국이 일곱이다.<br><br>맨 위에 하나가 더 있다. 아주 얕다.<br>안 세었다.`, poll:9 },
    { l:'② 바퀴를 찾는다.', dc:14, p:800,
      doom:{ title:'찾은 바퀴', what:'끼웠습니다', dc:14, sec:70,
        text:`무너진 돌 사이를 뒤졌다. 바퀴가 있다. 둘 다.<br><br>가져간 게 아니라 숨긴 것이다.<br>끼워 봤다. 맞는다. 축에 딱.<br><br>끼우고 나니 마차가 굴러간다. 안 밀었는데.<br>마부는 고친 마차를 끈다. 고쳤으면 끄는 게 일이다.`,
        dieText:`바퀴를 뺀 데는 이유가 있다.<br><br>못 가게 하려고 뺀 것이다.<br>회랑에 마차가 있다. 바퀴가 넷이다.` },
      good:`뒤지다 그만뒀다.<br><br>바퀴를 뺀 건 못 가게 하려고 한 것이다.<br>찾아서 끼우면 가게 된다.<br><br>안 찾았다. 바퀴 없는 채로 두는 게 맞다.`, flag:'leftItWheelless' }
  ] }
);

epicSlot('gate', 'driver').push(
{ title:'성문 — 비어 있는 끌채',
  text:`맨 앞 마차 끌채가 비어 있다.<br><br>
    끌 사람이 없다.<br>
    마부는 빈 끌채를 못 지나친다.<br><br>
    잡으면 끌게 된다.`,
  opts:[
    { l:'① 끌채를 묶어 둔다.', dc:13, kind:'bond', p:800,
      good:`끌채를 들어 올려 마차 위에 묶었다.<br><br>세워 두면 눈에 덜 띈다. 내려놓은 끌채는 잡으라는 모양이다.<br>올려 묶으면 아니다.<br><br>스물셋 대를 다 하지는 못했다. 맨 앞 것만 했다.`, flag:'tiedUpShaft',
      bad:`묶은 끌채가 도로 내려온다.<br><br>세 번 묶었다. 세 번 다 풀린다.<br>돌을 괴어 놓았다.`, poll:9 },
    { l:'② 끌채를 잡아 본다.', dc:14, p:800,
      doom:{ title:'잡은 끌채', what:'손이 안 놓입니다', dc:14, sec:70,
        text:`끌채를 잡았다. 무게만 보려고.<br><br>손에 맞는다. 오래 쥔 것처럼 맞는다.<br>당겨 봤다. 안 움직인다. 축이 휘어서.<br><br>놓으려는데 안 놓인다. 마부 손이 끌채를 안 놓는다.<br>배운 것이다. 놓으면 마차를 잃으니까.`,
        dieText:`마부는 끌채를 안 놓게 배운다.<br><br>잡지 않는 것까지는 안 배운다.<br>맨 앞 마차에 끌 사람이 생겼다.` },
      good:`손을 뻗다가 거뒀다.<br><br>잡으면 안 놓는다. 마부 손이 그렇게 배웠다.<br>안 잡는 것까지는 안 배웠으니 스스로 해야 한다.<br><br>주머니에 손을 넣고 지났다.`, flag:'pocketedHandsDriver' }
  ] }
);

epicSlot('forest', 'driver').push(
{ title:'검은 숲 — 들고 나온 것',
  text:`마차로는 못 들어간다.<br><br>
    안에서 뭘 꺼내려면 들고 나와야 한다.<br>
    마부는 사람이 들 수 있는 무게를 안다.<br><br>
    들고 나온 자국이 있는지가 문제다.`,
  opts:[
    { l:'① 발자국 깊이를 본다.', dc:13, kind:'sense', p:800,
      good:`가장자리 발자국이 나올 때 더 깊다.<br><br>들고 나왔다는 뜻이다. 무거운 걸.<br>발자국 폭이 좁다. 무거운 걸 들면 걸음이 좁아진다.<br><br>여덟 쌍쯤이다. 여덟 번 들고 나왔다.`, flag:'carriedOutEight',
      bad:`깊은 발자국이 들어갈 때다.<br><br>들고 들어갔다. 나올 때는 가볍다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 들어간 데를 따라간다.', dc:14, kind:'evade', p:800,
      doom:{ title:'따라간 안쪽', what:'좁아졌습니다', dc:14, sec:70,
        text:`발자국을 따라 트인 줄로 들어갔다.<br><br>걷기 좋다. 한 사람 폭이라 곧다.<br>가다 보니 좁아진다. 어깨가 스친다.<br><br>돌아서려는데 돌아설 폭이 없다. 마차를 돌릴 데가 없는 것과 같다.<br>마부는 돌릴 데를 먼저 본다. 이번에는 안 봤다.`,
        dieText:`들어가기 전에 돌릴 데를 본다.<br><br>마차든 사람이든 같다.<br>트인 줄에 발자국이 한 쌍 더 늘었다.` },
      good:`입구에서 돌아섰다.<br><br>들어가기 전에 돌릴 데를 본다. 마부가 제일 먼저 배우는 것이다.<br>여기는 돌릴 데가 없다.<br><br>안 들어갔다. 가장자리에서 발자국만 셌다.`, flag:'checkedTurnaround' }
  ] }
);

epicSlot('road', 'driver').push(
{ title:'끊긴 길 — 돌아간 자국',
  text:`스물셋 번 왔다가 돌아갔다.<br><br>
    마차가 못 가는 걸 알고 돌아갔다.<br>
    마부는 돌아가는 걸 잘한다.<br><br>
    다만 짐은 어떻게 됐는지 모른다.`,
  opts:[
    { l:'① 내린 자국이 있는지 본다.', dc:13, kind:'gaze', p:800,
      good:`경계석 앞에 내린 자국이 있다. 여럿.<br><br>싣고 와서 내려놓고 돌아갔다.<br>내려놓은 건 없어졌다. 사람이 들고 건넜다는 뜻이다.<br><br>마차는 못 가고 사람은 갔다. 짐도 갔다.`, flag:'unloadedAtEdge',
      bad:`내린 자국이 하나뿐이다.<br><br>스물셋 번 왔는데 한 번만 내렸다.<br>나머지는 안 내리고 도로 갔다.`, poll:9 },
    { l:'② 수레를 밀어 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'민 수레', what:'굴러갔습니다', dc:14, sec:70,
        text:`빈 수레를 경계 쪽으로 밀어 봤다. 어디까지 가나 보려고.<br><br>굴러간다. 세 걸음. 안 멈춘다.<br>더 간다. 안개로 들어간다.<br><br>안 보인다. 소리도 없다.<br>마부는 굴러간 수레를 쫓는다. 몸이 먼저 간다. 두 걸음 갔다.`,
        dieText:`굴러간 수레는 쫓게 되어 있다.<br><br>안 쫓으려면 안 밀어야 한다.<br>경계 앞에 바퀴 자국이 셋 걸음 나 있다.` },
      good:`손을 대다가 거뒀다.<br><br>밀면 굴러간다. 굴러가면 쫓는다.<br>마부 몸이 그렇게 배웠다.<br><br>안 밀었다. 바퀴에 돌을 괴어 뒀다.`, flag:'chockedTheWheel' }
  ] }
);
;

