      good:`들어온 게 스물넷, 나간 게 하나.<br><br>스물셋이 안 나갔다. 물건이면 재고다.<br>재고가 스물셋이면 장이 안 선 것이다.<br><br>안 팔린 게 아니라 안 나간 것이다. 둘은 다르다.`, flag:'stockNotSold',
