epicSlot('lake', 'merchant').push(
{ title:'거울 호수 — 비친 좌판',
  text:`물에 좌판이 비친다.<br><br>
    이쪽 물가에는 없다.<br>
    상인은 남의 좌판을 보면 뭘 파는지 본다.<br><br>
    저쪽 좌판에 물건이 많다.`,
  opts:[
    { l:'① 뭘 파는지 본다.', dc:13, kind:'gaze', p:750,
      good:`물건이 쌓여 있다. 이쪽 장터 것과 같은 것들이다.<br><br>다만 저쪽은 줄어들고 있다. 팔리는 중이다.<br>사는 사람이 있다는 뜻이다.<br><br>여기는 안 팔리고 저기는 팔린다. 장이 저쪽에 서 있다.`, flag:'marketIsThere',
      bad:`물건이 늘어난다.<br><br>파는 게 아니라 쌓이는 중이다. 이쪽 것이 넘어가는 것 같다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 값을 물어본다.', dc:14, p:800,
      doom:{ title:'물은 값', what:'거래가 시작됐습니다', dc:14, sec:70,
        text:`얼마냐고 물었다. 상인이 제일 먼저 하는 말이다.<br><br>비친 것이 손가락을 편다. 값을 부른다.<br>싸다. 아주 싸다.<br><br>싸면 산다. 상인은 싼 걸 못 지나친다.<br>값을 물은 순간 흥정이 시작됐다. 흥정은 사기 전에는 안 끝난다.`,
        dieText:`값을 물으면 사게 된다.<br><br>안 살 거면 값을 안 묻는다. 상인이 제일 먼저 배우는 것이다.<br>물가에 좌판이 하나 있다.` },
      good:`입을 열다가 다물었다.<br><br>값을 물으면 흥정이 시작된다. 흥정은 사야 끝난다.<br>안 살 거면 안 묻는다.<br><br>안 물었다. 물건만 봤다.`, flag:'didntAskPrice' }
  ] }
);

epicSlot('ruin', 'merchant').push(
{ title:'폐허 — 창고 자리',
  text:`회랑 한쪽이 창고였다.<br><br>
    선반 자국이 남아 있다.<br>
    상인은 창고를 보면 얼마나 쌓였었는지 안다.<br><br>
    자국 수로 안다.`,
  opts:[
    { l:'① 자국을 센다.', dc:13, kind:'gaze', p:750,
      good:`스물넷 자리다. 전부 비었다.<br><br>스물넷을 쌓았다가 스물넷을 다 냈다.<br>다 낸 창고는 장사가 잘된 것이다.<br><br>다만 낸 게 팔린 건지 옮겨진 건지 모른다.`, flag:'emptiedStore',
      bad:`자국이 스물다섯이다.<br><br>하나가 더 있다. 다른 자국보다 크다.<br>안 세었다.`, poll:9 },
    { l:'② 남은 게 있나 본다.', dc:12, kind:'sense', p:700,
      good:`선반 틈에 종이 조각이 있다. 값표다.<br><br>숫자가 적혀 있다. 물건 이름은 찢겼다.<br>값만 남았다.<br><br>상인은 값만 봐도 뭔지 짐작한다. 이 값이면 흔한 게 아니다.`, flag:'priceTagOnly',
      bad:`값표에 적힌 게 숫자가 아니다.<br><br>글자다. 짧다. 세 글자쯤.<br>안 읽었다.`, poll:9 }
  ] }
);

epicSlot('market', 'merchant').push(
{ title:'장터 — 사는 사람이 없다',
  text:`좌판이 스물셋이다.<br><br>
    전부 파는 쪽이다.<br>
    상인은 사는 사람이 없는 장을 안다.<br><br>
    파는 사람만 있으면 장이 아니다.`,
  opts:[
    { l:'① 왜 안 사는지 본다.', dc:13, kind:'sense', p:750,
      good:`주인들이 고개를 숙이고 있다. 사러 온 사람을 안 본다.<br><br>안 보면 흥정이 안 된다. 흥정이 없으면 거래도 없다.<br>일부러 안 보는 것이다.<br><br>팔 생각이 없으면서 좌판을 펴 놓았다.`, flag:'notReallySelling',
      bad:`하나가 고개를 든다.<br><br>사러 온 줄 안 것이다. 팔 생각이 있는 하나다.<br>눈을 피했다.`, poll:9 },
    { l:'② 좌판 수를 센다.', dc:12, kind:'gaze', p:700,
      good:`스물셋이다. 집 수와 같다. 비석 수와도 같다.<br><br>한 집에 한 좌판이다.<br>마을 사람이 여기 나와 있었다는 뜻이다.<br><br>나와 있는데 아무도 안 판다.`, flag:'oneStallPerHouse',
      bad:`세는데 스물넷이다.<br><br>끝에 하나가 더 있다. 물건이 없는 좌판이다.<br>안 세었다.`, poll:9 }
  ] }
);

epicSlot('road', 'merchant').push(
{ title:'끊긴 길 — 오가는 게 없다',
  text:`길이 끊겼다.<br><br>
    상인은 끊긴 길을 제일 싫어한다.<br>
    오가야 장사가 된다.<br><br>
    끊기면 값이 안 돈다.`,
  opts:[
    { l:'① 건넌 자국을 본다.', dc:12, kind:'gaze', p:700,
      good:`건너간 자국이 하나다. 돌아온 건 없다.<br><br>하나 나가고 안 돌아왔다. 물건이든 사람이든.<br>상인 셈으로는 손해다.<br><br>나간 게 안 돌아오면 그건 거래가 아니라 잃은 것이다.`, flag:'lossNotTrade' },
    { l:'② 건너편에 장이 있나 본다.', dc:14, kind:'sense', p:800,
      doom:{ title:'본 건너편', what:'장이 서 있었습니다', dc:14, sec:70,
        text:`안개 너머를 가늠해 봤다. 상인은 장이 어디 서는지 냄새로 안다.<br><br>사람 소리가 난다. 흥정하는 소리다.<br>값을 부르고 깎는 소리. 아는 소리다.<br><br>장이 서 있다. 저쪽에.<br>상인은 장이 서면 간다. 안 가면 장사가 안 된다. 발이 먼저 간다.`,
        dieText:`장이 서 있는 데로 가는 게 상인이다.<br><br>가서 파는 게 아니라 팔리는 장도 있다.<br>안개 위에 자국이 둘이 됐다.` },
      good:`귀를 기울이다 막았다.<br><br>소리가 났다. 흥정하는 소리였다.<br>장이 서 있으면 가고 싶어진다. 그게 상인이다.<br><br>안 들었다. 귀를 막고 돌아섰다.`, flag:'coveredEarsMerchant' }
  ] }
);
;

// ---------- epic-merchant-2.js ----------
// ==========================================
// ★ 상인 확장 2/4 — 동료 · 미니게임 중심
// index.html 에서 epic-merchant-1.js 다음에 불러온다
// ==========================================

epicSlot('market', 'merchant').push(
{ title:'장터 — 둘이 흥정한다',
  text:`혼자 흥정하면 값이 안 내려간다.<br><br>
    사는 쪽이 둘이면 파는 쪽이 고민한다.<br>
    상인은 둘로 흥정하는 법을 안다.<br><br>
    하나가 비싸다 하고 하나가 산다 하면 값이 갈린다.`,
  opts:[
    { l:'① 동료와 나눠 흥정한다.', co:'sync',
      coOpt:{ ask:'제가 사겠다고 하면 비싸다고 해 주십시오. 그것만 하시면 됩니다.', sec:60, p:1000,
        text:`둘로 흥정하면 값이 갈린다.`,
        doneText:`이쪽이 사겠다고 했다. 저쪽이 비싸다고 했다.<br><br>주인이 고개를 들었다. 처음으로.<br>값을 내린다. 손가락을 하나 접는다.<br><br>안 샀다. 값만 확인하고 물러났다.<br>저쪽이 왜 안 사냐고 물었다. 값을 알면 됐다고 했다.`,
        failText:`혼자 흥정했다. 사겠다고만 했다.<br><br>값이 안 내려간다. 주인이 고개를 안 든다.<br>얼마인지도 못 들었다.` },
      good:`값을 알았다.`, bad:`못 들었다.`, flag:'learnedThePrice' },
    { l:'② 저울로 값을 맞춘다.', mini:'scale', miniOpt:{ p:800, target:23, pool:[3,5,6,7,10,12] },
      good:`수평이 됐다.<br><br>주인이 물건을 밀어 준다. 거래가 성립한다.<br>안 받았다. 성립하는 것만 봤다.<br><br>성립시키고 안 받는 건 상인이 잘 안 한다. 여기서는 그게 낫다.`, flag:'matchedTheScale',
      bad:`기울었다.<br><br>많이 얹으면 욕심이고 적게 얹으면 도둑이다.<br>정확히 맞춰야 하는데 못 맞췄다.` }
  ] }
);

epicSlot('gate', 'merchant').push(
{ title:'성문 — 둘이 센다',
  text:`아치 금과 돌 금이 안 맞는다.<br><br>
    혼자 세면 어느 쪽이 틀렸는지 모른다.<br>
    각자 하나씩 세면 갈린다.<br><br>
    상인은 두 장부를 맞춰 보는 게 일이다.`,
  opts:[
    { l:'① 동료와 나눠 센다.', co:'sync',
      coOpt:{ ask:'저 돌에 새겨진 금을 세 주십시오. 제가 아치를 세겠습니다.', sec:60, p:1000,
        text:`두 장부를 맞춰 봐야 어디가 틀렸는지 안다.`,
        doneText:`갈라 셌다. 아치는 스물넷, 돌은 스물다섯이다.<br><br>하나가 더 세어졌다. 돌 쪽이다.<br>세는 자리에서 하나 더 셌다는 뜻이다.<br><br>세고 안 들여보낸 것이 하나 있다.<br>저쪽이 그게 무슨 뜻이냐고 물었다. 모르겠다고 했다.`,
        failText:`혼자 셌다. 아치를 세고 돌을 세니 앞엣것을 잊는다.<br><br>세 번 왔다 갔다 했다.<br>어느 쪽이 큰지도 모르겠다.` },
      good:`하나 차이를 찾았다.`, bad:`모르겠다.`, flag:'countedOneExtra' },
    { l:'② 세는 돌 자국을 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`돌 위 닳은 자국을 순서대로 짚었다. 여섯 자리.<br><br>맞췄다. 물건 놓던 자리가 크기별로 나뉘어 있다.<br>큰 것 놓는 데가 제일 닳았다.<br><br>큰 것이 자주 지났다. 사람만 한 것도 지날 만하다.`, flag:'largestWorn',
      bad:`자국이 고르다.<br><br>크기별로 안 나뉜다. 순서를 못 잡겠다.<br>그만뒀다.` }
  ] }
);

epicSlot('village', 'merchant').push(
{ title:'빈 마을 — 둘이 값을 매긴다',
  text:`집마다 물건이 하나씩이다.<br><br>
    혼자 값을 매기면 이쪽 셈뿐이다.<br>
    둘이 매겨 같으면 그게 값이다.<br><br>
    한 사람이 매긴 건 값이 아니라 생각이다.`,
  opts:[
    { l:'① 동료와 따로 매긴다.', co:'witness',
      coOpt:{ ask:'이 물건이 얼마쯤 할지 말해 주십시오. 제 값은 나중에 말하겠습니다.', sec:60, p:1000,
        text:`둘이 매겨 같으면 그게 값이다.`,
        doneText:`따로 매겨 맞춰 봤다. 거의 같다.<br><br>세 집을 그렇게 했다. 세 번 다 비슷했다.<br>물건이 다른데 값이 같다. 재서 나눈 게 맞다.<br><br>저쪽이 물었다. 왜 값이 같냐고.<br>고르게 나누려면 값을 맞춰야 한다고 했다.`,
        failText:`혼자 매겼다. 맞는지 모르겠다.<br><br>세 번 매겨서 세 번 다르다.<br>이쪽 셈을 못 믿겠다.` },
      good:`값이 확인됐다.`, bad:`못 믿겠다.`, flag:'confirmedValues' },
    { l:'② 물건 무게를 견준다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,10] },
      good:`집집 물건 무게를 견줬다.<br><br>맞췄다. 무게는 제각각인데 값은 같다.<br>무게로 나눈 게 아니라 값으로 나눴다.<br><br>값을 아는 사람이 나눴다. 상인이 했다.`, flag:'dividedByValue',
      bad:`무게가 안 잡힌다.<br><br>가벼워 보이는데 무겁다. 들어 보지 않은 것도 있다.<br>그만뒀다.` }
  ] }
);

epicSlot('castle', 'merchant').push(
{ title:'성 — 둘이 장부를 읽는다',
  text:`장부가 스물넷 줄이다.<br><br>
    혼자 읽으면 같은 데서 눈이 넘어간다.<br>
    하나가 읽고 하나가 짚어야 한다.<br><br>
    상인은 장부를 둘이 읽는다.`,
  opts:[
    { l:'① 동료가 짚는다.', co:'sync',
      coOpt:{ ask:'한 줄씩 짚어 주십시오. 제가 읽겠습니다.', sec:60, p:1000,
        text:`읽으면서 짚으면 눈이 앞서간다.`,
        doneText:`저쪽이 짚고 이쪽이 읽었다. 스물넷 줄.<br><br>열아홉째 줄에서 저쪽 손가락이 멈췄다. 날짜가 없다고 했다.<br>다시 보니 그 줄만 날짜 칸이 비었다.<br><br>날짜 없이 들어온 것이 하나 있다.<br>언제 들어왔는지 모르는 게 하나 있다는 뜻이다.`,
        failText:`혼자 읽었다. 열다섯쯤에서 눈이 흐려진다.<br><br>나머지는 대충 넘겼다.<br>빠진 줄이 있는지는 모른다.` },
      good:`빠진 줄을 찾았다.`, bad:`못 찾았다.`, flag:'nineteenthNoDate' },
    { l:'② 장부 두께를 견준다.', mini:'scale', miniOpt:{ p:750, target:19, pool:[2,3,5,6,8,10] },
      good:`남은 종이와 쓴 종이를 견줬다.<br><br>맞췄다. 쓴 게 훨씬 적다. 남은 게 많다.<br>더 적으려고 만든 장부다.<br><br>스물넷에서 멈췄다. 더 적을 자리는 많은데.`, flag:'roomForMore',
      bad:`두께가 안 잡힌다.<br><br>남은 종이가 늘었다 줄었다 한다.<br>덮었다.` }
  ] }
);

epicSlot('temple', 'merchant').push(
{ title:'신전 — 둘이 바친다',
  text:`바치는 데는 값을 안 센다.<br><br>
    혼자 바치면 아까운 게 센다.<br>
    둘이 바치면 덜 아깝다.<br><br>
    나눠 내면 각자 반이다.`,
  opts:[
    { l:'① 동료와 나눠 낸다.', co:'handoff',
      coOpt:{ ask:'반씩 냅시다. 아까운 걸 내는 게 바치는 겁니다.', sec:55, p:950,
        text:`나눠 내면 각자 반이다.`,
        doneText:`각자 하나씩 꺼내 놓았다. 이쪽이 값나가는 것으로.<br><br>저쪽은 뭔지 모를 것을 놓았다. 주운 거라고 했다.<br>값을 안 물었다. 물으면 거래가 된다.<br><br>촛불이 두 번 흔들렸다.<br>저쪽 것이 이쪽 것보다 아까운 것이었는지도 모르겠다.`,
        failText:`혼자 놓았다. 값나가는 것으로 놓으려다 싼 걸로 바꿨다.<br><br>바꾸고 나니 마음에 걸린다.<br>바꾼 걸 아는 건 이쪽뿐인데 그래서 더 걸린다.` },
      good:`둘이 냈다.`, bad:`바꿔 놓았다.`, flag:'sharedOffering' },
    { l:'② 놓인 것들의 값을 순서대로 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`값이 나가는 순서로 짚었다. 여섯 개.<br><br>맞췄다. 뒤로 갈수록 싸진다.<br>처음엔 좋은 걸 바치다 나중엔 아무거나 바쳤다.<br><br>가진 게 줄었다는 뜻이다.`, flag:'cheaperOverTime',
      bad:`값이 안 잡힌다.<br><br>매기려는 순간 다른 값이 떠오른다.<br>그만뒀다.` }
  ] }
);

epicSlot('forest', 'merchant').push(
{ title:'검은 숲 — 둘이 재 본다',
  text:`나무가 값나간다.<br><br>
    혼자 재면 아쉬워서 크게 잰다.<br>
    둘이 재면 정확하다.<br><br>
    상인은 아쉬우면 셈이 틀어진다는 걸 안다.`,
  opts:[
    { l:'① 동료와 나무를 잰다.', co:'sync',
      coOpt:{ ask:'줄 한쪽을 잡아 주십시오. 둘레를 재겠습니다.', sec:60, p:1000,
        text:`아쉬우면 크게 재게 된다.`,
        doneText:`줄로 둘레를 쟀다. 저쪽이 한쪽을 잡았다.<br><br>크다. 이만한 나무는 값이 크다.<br>다만 벨 수가 없다. 베도 못 가져간다.<br><br>저쪽이 그럼 값이 얼마냐고 물었다.<br>없다고 했다. 못 가져가는 건 값이 없다.`,
        failText:`혼자 쟀다. 한 손으로 줄을 잡으니 늘어진다.<br><br>실제보다 크게 나온다. 아쉬워서 더 크게 봤다.<br>못 믿을 값이다.` },
      good:`정확히 쟀다.`, bad:`크게 쟀다.`, flag:'measuredHonestly' },
    { l:'② 베인 나무를 찾아 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`아문 자국의 오래된 순서로 짚었다. 여섯 그루.<br><br>맞췄다. 전부 아물었는데 하나만 안 아물었다.<br>그게 제일 새것이다.<br><br>최근에 베었다. 아직 안 아물 만큼 최근에.`, flag:'oneFreshCut',
      bad:`자국이 다 비슷하다.<br><br>순서를 못 잡겠다. 아무는 속도가 제각각이다.<br>그만뒀다.` }
  ] }
);

epicSlot('grave', 'merchant').push(
{ title:'묘지 — 둘이 본다',
  text:`봉분 하나만 모양이 다르다.<br><br>
    혼자 보면 기분 탓인지 모른다.<br>
    둘이 보면 확실해진다.<br><br>
    상인은 확실하지 않은 건 안 친다.`,
  opts:[
    { l:'① 동료와 같이 본다.', co:'witness',
      coOpt:{ ask:'저 봉분이 다른 것과 다른지 봐 주십시오.', sec:60, p:1000,
        text:`둘이 보면 확실해진다.`,
        doneText:`둘이 봤다. 저쪽도 다르다고 했다.<br><br>각이 져 있다. 나머지는 둥근데 그것만 모가 났다.<br>관이 들었다는 뜻이다.<br><br>스물둘은 관 없이 묻고 하나만 관을 썼다.<br>값을 들인 하나다. 안 팠다. 둘 다 안 파자고 했다.`,
        failText:`혼자 봤다. 다른 것 같기도 하고 아닌 것 같기도 하다.<br><br>세 번 봤다. 볼 때마다 다르게 보인다.<br>확실하지 않으니 안 친 걸로 했다.` },
      good:`관이 든 걸 확인했다.`, bad:`확실하지 않다.`, flag:'oneHasCoffin' },
    { l:'② 봉분 크기를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`스물셋 크기를 견줬다.<br><br>맞췄다. 스물둘이 같고 하나가 크다.<br>관이 든 만큼 크다.<br><br>크기 차이가 관 하나 부피다. 셈이 맞는다.`, flag:'coffinSized',
      bad:`크기가 잴 때마다 다르다.<br><br>견줄 수가 없다. 그만뒀다.` }
  ] }
);

epicSlot('tower', 'merchant').push(
{ title:'탑 — 둘이 셈한다',
  text:`스물넷으로 예순아홉이 안 나온다.<br><br>
    혼자 셈하면 틀린 줄 안다.<br>
    둘이 셈해서 같으면 셈이 아니라 세상이 틀린 것이다.<br><br>
    상인은 그 구분을 중히 여긴다.`,
  opts:[
    { l:'① 동료와 따로 셈한다.', co:'witness',
      coOpt:{ ask:'집과 비석과 좌판을 세어 주십시오. 제 수는 나중에.', sec:60, p:1000,
        text:`둘이 같으면 셈이 아니라 세상이 틀린 것이다.`,
        doneText:`따로 세고 맞췄다. 둘 다 스물셋씩이라 했다.<br><br>합치면 예순아홉. 들어온 건 스물넷.<br>셈이 안 맞는다. 둘 다 같은 답이 나왔으니 셈은 맞았다.<br><br>저쪽이 물었다. 그럼 뭐가 틀린 거냐고.<br>들어온 수가 스물넷이 아니거나, 같은 게 세 번 세어졌거나.`,
        failText:`혼자 셌다. 세 군데를 세다 보니 섞인다.<br><br>예순이었다가 일흔이 된다.<br>셈이 틀렸는지 세상이 틀렸는지 모르겠다.` },
      good:`셈은 맞았다.`, bad:`모르겠다.`, flag:'sameThingCountedThrice' },
    { l:'② 세 군데 배치를 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`세 군데 배치를 순서대로 짚었다. 일곱 자리.<br><br>맞췄다. 배치가 같다. 겹쳐 놓으면 딱 맞는다.<br>같은 그림을 세 군데에 그렸다.<br><br>같은 걸 세 번 세면 세 배가 나온다. 예순아홉이 그래서 나왔다.`, flag:'threeCopies',
      bad:`배치가 안 맞는다.<br><br>비슷한데 다르다. 겹쳐지지 않는다.<br>그만뒀다.` }
  ] }
);

epicSlot('lake', 'merchant').push(
{ title:'거울 호수 — 둘이 등진다',
  text:`저쪽 좌판에서 물건이 팔린다.<br><br>
    혼자 보면 값을 묻게 된다.<br>
    상인은 팔리는 걸 보면 못 지나친다.<br><br>
    막아 줄 사람이 필요하다.`,
  opts:[
    { l:'① 동료가 막는다.', co:'standin',
      coOpt:{ ask:'제가 뭐라고 말하려 하면 입을 막아 주십시오.', sec:60, p:1050,
        text:`값을 물으면 흥정이 시작된다.`,
        doneText:`물가에 섰다. 입이 열렸다. 저쪽이 손으로 막았다.<br><br>세 번 그랬다. 세 번 다 막았다.<br>비친 것이 손가락을 펴려다 만다. 값을 못 부른다.<br><br>물어야 부른다. 안 물으면 못 부른다.<br>물러날 때까지 저쪽이 손을 안 뗐다.`,
        failText:`혼자 섰다. 입이 열린다.<br><br>한 마디가 나갔다. 값이 아니라 감탄이었다.<br>다행이다. 감탄은 흥정이 아니다.` },
      good:`안 물었다.`, bad:`한 마디 나갔다.`, flag:'mouthCovered' }
  ] }
);

epicSlot('ruin', 'merchant').push(
{ title:'폐허 — 둘이 자국을 센다',
  text:`선반 자국이 스물넷이다.<br><br>
    혼자 세면 겹친 데서 놓친다.<br>
    둘이 갈라 세면 안 놓친다.<br><br>
    상인은 재고를 둘이 센다.`,
  opts:[
    { l:'① 동료와 갈라 센다.', co:'sync',
      coOpt:{ ask:'저쪽 선반을 세 주십시오. 네모 자국만 세시면 됩니다.', sec:60, p:1000,
        text:`재고는 둘이 센다.`,
        doneText:`갈라 셌다. 이쪽 열둘, 저쪽 열둘. 스물넷이다.<br><br>저쪽이 말했다. 자기 쪽 하나는 자국이 크다고.<br>가서 보니 다른 것 두 배다.<br><br>큰 게 하나 있었다. 나머지 스물셋은 같은 크기다.<br>스물셋과 하나. 또 그 셈이다.`,
        failText:`혼자 셌다. 겹친 데서 놓쳤다.<br><br>스물둘이었다가 스물다섯이 된다.<br>재고를 못 세는 상인은 상인이 아닌데.` },
      good:`큰 자국을 찾았다.`, bad:`못 셌다.`, flag:'oneLargeSlot' },
    { l:'② 값표 숫자를 견준다.', mini:'scale', miniOpt:{ p:750, target:22, pool:[3,5,6,8,9,12] },
      good:`값표 숫자를 아는 물건 값과 견줬다.<br><br>맞췄다. 아주 비싸다. 집 한 채 값쯤이다.<br>이만한 값이면 흔한 물건이 아니다.<br><br>스물넷 개를 이 값에 쌓아 뒀다. 큰 장사였다.`, flag:'veryExpensive',
      bad:`값이 어림이 안 된다.<br><br>아는 물건 중에 이만한 게 없다.<br>그만뒀다.` }
  ] }
);

epicSlot('road', 'merchant').push(
{ title:'끊긴 길 — 둘이 귀를 막는다',
  text:`건너편에서 흥정하는 소리가 난다.<br><br>
    혼자 들으면 가게 된다.<br>
    상인은 장이 서면 간다.<br><br>
    잡아 줄 사람이 필요하다.`,
  opts:[
    { l:'① 동료가 잡는다.', co:'standin',
      coOpt:{ ask:'제가 앞으로 가려 하면 잡아 주십시오. 소리가 들립니다.', sec:60, p:1050,
        text:`상인은 장이 서면 간다.`,
        doneText:`귀를 막았는데도 들린다. 발이 앞으로 갔다.<br><br>저쪽이 팔을 잡았다. 세게.<br>안 놓았다. 한 걸음도 못 갔다.<br><br>저쪽은 아무 소리도 안 들린다고 했다.<br>상인 귀에만 들리는 소리가 있다.`,
        failText:`혼자 섰다. 귀를 막았다.<br><br>막은 손 안에서 들린다. 값 부르는 소리.<br>두 걸음 갔다. 정신을 차리고 물러났다.` },
      good:`한 걸음도 안 갔다.`, bad:`두 걸음 갔다.`, flag:'pulledBackFromMarket' },
    { l:'② 돌을 겨눠 던진다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`안개 쪽으로 던졌다. 두 번 닿았다.<br><br>가장자리에서는 소리가 난다. 안쪽은 안 난다.<br>소리가 안 나는 데까지가 땅이 아니다.<br><br>흥정 소리는 땅이 없는 데서 난다.`, flag:'soundFromNowhere',
      bad:`세 번 다 안쪽으로 갔다.<br><br>소리가 하나도 안 났다.<br>돌을 잃었다.` }
  ] }
);
;

